"""Install swe_tools into the repository (git-excluded)."""
import os, sys

FILES = {'_ws.py': '"""Shared helpers: find the repository, run commands, keep output short."""\n\nimport os\nimport subprocess\nimport sys\n\n\ndef workspace():\n    for cand in (os.environ.get("SWE_WS"), os.environ.get("PWD"), os.getcwd(), "/workspace"):\n        if cand and os.path.isdir(os.path.join(cand, ".git")):\n            return cand\n    here = os.path.dirname(os.path.abspath(__file__))\n    parent = os.path.dirname(here)\n    if os.path.isdir(os.path.join(parent, ".git")):\n        return parent\n    sys.exit("error: repository not found")\n\n\ndef sh(cmd, cwd, timeout=120):\n    try:\n        r = subprocess.run(cmd, cwd=cwd, shell=isinstance(cmd, str), capture_output=True, text=True, timeout=timeout)\n        return r.returncode, r.stdout, r.stderr\n    except subprocess.TimeoutExpired as e:\n        return 124, (e.stdout or "") if isinstance(e.stdout, str) else "", "TIMEOUT after %ss" % timeout\n\n\ndef tracked_py(ws):\n    _, out, _ = sh(["git", "ls-files", "*.py"], ws)\n    return [f for f in out.splitlines() if f]\n\n\ndef is_test_path(path):\n    parts = path.split("/")\n    name = parts[-1]\n    return ("tests" in parts or "test" in parts or name.startswith("test_") or name.endswith("_test.py")\n            or name == "conftest.py")\n\n\ndef changed_files(ws):\n    """Modified tracked files plus new untracked files (what submit_patch would include)."""\n    _, mod, _ = sh(["git", "diff", "--name-only", "HEAD"], ws)\n    _, new, _ = sh(["git", "ls-files", "--others", "--exclude-standard"], ws)\n    return [f for f in mod.splitlines() if f], [f for f in new.splitlines() if f]\n\n\ndef warn_if_repeated(argv):\n    """Tell the model when it re-runs an identical tool command (Gemma tends to loop)."""\n    import hashlib\n    import tempfile\n    key = hashlib.sha1("\\0".join(argv).encode()).hexdigest()[:16]\n    path = os.path.join(tempfile.gettempdir(), ".swetools_seen")\n    try:\n        with open(path) as fh:\n            seen = set(fh.read().split())\n    except OSError:\n        seen = set()\n    if key in seen:\n        print("NOTE: you already ran this exact command. Repeating it gives the same answer: use what you "\n              "learned and take the next step (edit, check.py, or submit_patch).\\n")\n    else:\n        try:\n            with open(path, "a") as fh:\n                fh.write(key + "\\n")\n        except OSError:\n            pass\n\n\ndef _state_path():\n    import tempfile\n    return os.path.join(tempfile.gettempdir(), ".swetools_state.json")\n\n\ndef load_state():\n    import json\n    try:\n        with open(_state_path()) as fh:\n            return json.load(fh)\n    except (OSError, ValueError):\n        return {}\n\n\ndef save_state(state):\n    import json\n    try:\n        with open(_state_path(), "w") as fh:\n            json.dump(state, fh)\n    except OSError:\n        pass\n\n\ndef digest(*parts):\n    import hashlib\n    return hashlib.sha1("\\0".join(parts).encode("utf-8", "replace")).hexdigest()[:16]\n', 'check.py': '"""Check the current patch before submit_patch().\n\nusage: python3 .swetools/check.py --repro /tmp/repro.py [TEST_FILE ...]\n\n0. With --repro, runs the reproduction script WITHOUT your change and WITH it:\n   a correct repro exits non-zero (AssertionError) before and 0 after.\n\n1. Lists what the patch contains and flags problems: files under tests/,\n   conftest.py / pytest.ini changes, stray new files (scratch scripts).\n2. Compiles and imports every changed Python module.\n3. Runs the test files for the changed code (or the TEST_FILEs given) and,\n   for any failure, reruns it without your change to tell you whether YOUR\n   change caused it.\nEnds with a one-line VERDICT.\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom _ws import changed_files, is_test_path, load_state, save_state, sh, tracked_py, warn_if_repeated, workspace  # noqa: E402\n\nPYTEST = "python3 -m pytest -q -p no:cacheprovider -o addopts=\'\' -p no:anyio --import-mode=importlib"\n\n\ndef module_name(path):\n    p = path[:-3] if path.endswith(".py") else path\n    for prefix in ("src/",):\n        if p.startswith(prefix):\n            p = p[len(prefix):]\n    p = p.replace("/", ".")\n    return p[:-9] if p.endswith(".__init__") else p\n\n\ndef related_tests(ws, changed_src):\n    tests = [t for t in tracked_py(ws) if is_test_path(t) and os.path.basename(t) != "conftest.py"]\n    scores = {}\n    mods = [module_name(f) for f in changed_src]\n    stems = [os.path.splitext(os.path.basename(f))[0] for f in changed_src]\n    for t in tests:\n        base = os.path.basename(t)\n        s = 0\n        for stem in stems:\n            if stem != "__init__" and base in ("test_%s.py" % stem, "%s_test.py" % stem):\n                s += 50\n        try:\n            with open(os.path.join(ws, t), encoding="utf-8", errors="replace") as fh:\n                text = fh.read()\n        except OSError:\n            continue\n        for mod in mods:\n            if mod and ("import " + mod in text or "from " + mod + " " in text or "from " + mod + "." in text):\n                s += 10\n        if s:\n            scores[t] = s\n    return [t for t, _ in sorted(scores.items(), key=lambda kv: -kv[1])[:4]]\n\n\ndef removed_lines(ws):\n    """Non-trivial lines the patch removed or replaced, with their file."""\n    _, diff, _ = sh(["git", "diff", "-U0", "HEAD", "--", "*.py"], ws)\n    out, cur = [], None\n    skip = ("#", \'"\' * 3, "\'" * 3, "import ", "from ")\n    for line in diff.splitlines():\n        if line.startswith("--- a/"):\n            cur = line[6:]\n        elif line.startswith("-") and not line.startswith("---") and cur and not is_test_path(cur):\n            text = line[1:].strip()\n            if len(text) >= 14 and not text.startswith(skip):\n                out.append((cur, text))\n    return out\n\n\ndef sibling_sweep(ws):\n    """Places that still contain code the patch changed elsewhere (same bug, other copy)."""\n    notes, seen = [], set()\n    for f, text in removed_lines(ws)[:12]:\n        if text in seen:\n            continue\n        seen.add(text)\n        _, out, _ = sh(["git", "grep", "-n", "-F", "-e", text, "--", "*.py"], ws)\n        for hit in out.splitlines()[:4]:\n            path = hit.split(":", 1)[0]\n            if not is_test_path(path):\n                notes.append("%s  still has: %s" % (":".join(hit.split(":", 2)[:2]), text[:90]))\n    return notes[:6]\n\n\ndef changed_names(ws):\n    """Functions/classes around the changed hunks (from the diff hunk headers)."""\n    _, diff, _ = sh(["git", "diff", "HEAD", "--", "*.py"], ws)\n    names = set()\n    for m in re.finditer(r"^@@[^@]*@@\\s*(?:async\\s+)?(?:def|class)\\s+(\\w+)", diff, re.M):\n        names.add(m.group(1))\n    for m in re.finditer(r"^\\+\\s*(?:async\\s+)?(?:def|class)\\s+(\\w+)", diff, re.M):\n        names.add(m.group(1))\n    return [n for n in names if not n.startswith("__") and len(n) > 3]\n\n\ndef tests_mentioning(ws, names, exclude):\n    if not names:\n        return []\n    tests = [t for t in tracked_py(ws) if is_test_path(t) and os.path.basename(t) != "conftest.py"]\n    hits = {}\n    for t in tests:\n        if t in exclude:\n            continue\n        try:\n            with open(os.path.join(ws, t), encoding="utf-8", errors="replace") as fh:\n                text = fh.read()\n        except OSError:\n            continue\n        c = sum(text.count(n) for n in names)\n        if c:\n            hits[t] = c\n    return [t for t, _ in sorted(hits.items(), key=lambda kv: -kv[1])[:2]]\n\n\ndef failed_ids(out):\n    return sorted(set(re.findall(r"^(?:FAILED|ERROR) (\\S+)", out, re.M)))\n\n\ndef run_repro(ws, repro):\n    """Run the repro with the change stashed (before) and applied (after)."""\n    if not os.path.isfile(repro):\n        return ["repro script %s not found: write it first (in /tmp)" % repro]\n    cmd = "timeout 90 python3 -B %s 2>&1 | tail -6" % repro\n    _, st, _ = sh("git stash push -q -u -- . && echo ok", ws, timeout=60)\n    try:\n        code0, out0, _ = sh(["bash", "-c", "set -o pipefail; " + cmd], ws, timeout=120)\n    finally:\n        if "ok" in st:\n            sh("git stash pop -q", ws, timeout=60)\n    code1, out1, _ = sh(["bash", "-c", "set -o pipefail; " + cmd], ws, timeout=120)\n    print("REPRO %s" % repro)\n    print("  without your change: %s" % ("FAILS (exit %d)" % code0 if code0 else "passes"))\n    for line in out0.strip().splitlines()[-3:]:\n        print("      " + line[:200])\n    print("  with your change:    %s" % ("FAILS (exit %d)" % code1 if code1 else "passes"))\n    for line in out1.strip().splitlines()[-4:]:\n        print("      " + line[:200])\n    problems = []\n    if not code0:\n        problems.append("the repro passes WITHOUT your change, so it does not reproduce the issue: make it use the "\n                        "public API exactly as the issue describes and assert the expected result; if it truly "\n                        "passes, the bug is elsewhere - try other input shapes and entry points. (If the issue "\n                        "asks for no behaviour change, e.g. a refactor or speed-up, run check.py without --repro.)")\n    if code1:\n        problems.append("the repro still fails WITH your change: the fix does not work yet")\n    return problems\n\n\ndef main():\n    ws = workspace()\n    _, diff, _ = sh(["git", "diff", "HEAD"], ws)\n    warn_if_repeated(sys.argv + [diff])\n    args = sys.argv[1:]\n    repro = None\n    state = load_state()\n    if "--repro" in args:\n        i = args.index("--repro")\n        repro = args[i + 1] if i + 1 < len(args) else ""\n        del args[i:i + 2]\n        if repro:\n            state["repro"] = repro\n            save_state(state)\n    elif state.get("repro") and os.path.isfile(state["repro"]):\n        repro = state["repro"]\n        print("(using your repro from earlier: %s)" % repro)\n    modified, new = changed_files(ws)\n    problems = []\n    print("PATCH CONTENTS")\n    for f in modified:\n        print("  M " + f)\n    for f in new:\n        print("  A " + f)\n    if not modified and not new:\n        print("  (empty) - you have not changed anything yet")\n\n    for f in modified + new:\n        base = os.path.basename(f)\n        if is_test_path(f) or base in ("pytest.ini", "conftest.py", "setup.cfg", "tox.ini"):\n            problems.append("revert %s (test/config files are reset or break grading): git checkout -- %s" % (f, f)\n                            if f in modified else "delete %s: rm %s" % (f, f))\n    for f in new:\n        if not is_test_path(f) and (f.count("/") == 0 or re.search(r"(repro|debug|scratch|tmp|test_fix|reproduce)", f)):\n            problems.append("stray new file %s - delete it unless it is real library source: rm %s" % (f, f))\n\n    changed_src = [f for f in modified + new if f.endswith(".py") and not is_test_path(f)]\n    for f in changed_src:\n        code, out, err = sh(["python3", "-m", "py_compile", f], ws, timeout=60)\n        if code:\n            problems.append("SYNTAX ERROR in %s: %s" % (f, (err or out).strip().splitlines()[-1][:200]))\n    for f in changed_src:\n        mod = module_name(f)\n        if mod.startswith(("docs_src", "scripts", "docs.")):\n            continue\n        code, out, err = sh(["python3", "-c", "import " + mod], ws, timeout=60)\n        if code:\n            last = (err or out).strip().splitlines()[-1:] or ["?"]\n            problems.append("import %s fails: %s" % (mod, last[0][:200]))\n\n    if repro is not None:\n        print()\n        problems += run_repro(ws, repro)\n    given = [t for t in args if t.strip()]\n    tests = [t for t in given if is_test_path(t)]\n    extra_src = [t for t in given if not is_test_path(t) and t.endswith(".py")]\n    if not tests:\n        tests = related_tests(ws, changed_src + [f for f in extra_src if f not in changed_src])\n        tests = (tests + tests_mentioning(ws, changed_names(ws), tests))[:5]\n    print("\\nTESTS: " + (" ".join(tests) if tests else "no related test files found"))\n    caused = []\n    if tests:\n        code, out, err = sh(PYTEST + " " + " ".join(tests) + " 2>&1 | tail -40", ws, timeout=200)\n        summary = [l for l in out.splitlines() if re.search(r"\\b(passed|failed|error)", l)]\n        print("  " + (summary[-1] if summary else out.strip().splitlines()[-1:] and out.strip().splitlines()[-1] or "no output"))\n        if "no tests ran" in out or not summary:\n            problems.append("no tests ran from %s: pass the test file(s) for the code you changed" % " ".join(tests))\n        fails = failed_ids(out)\n        if fails:\n            _, st, _ = sh("git stash push -q --keep-index -- . && echo ok", ws, timeout=60)\n            try:\n                code0, out0, _ = sh(PYTEST + " " + " ".join(sorted(set(f.split(\'::\')[0] for f in fails))) +\n                                    " 2>&1 | tail -40", ws, timeout=200)\n            finally:\n                if "ok" in st:\n                    sh("git stash pop -q", ws, timeout=60)\n            before = set(failed_ids(out0))\n            empty_patch = not modified and not new\n            for fid in fails:\n                is_caused = fid not in before and not empty_patch\n                tag = "CAUSED BY YOUR CHANGE" if is_caused else "ALSO FAILS WITHOUT YOUR CHANGE (ignore)"\n                print("  %s  <- %s" % (fid, tag))\n                if is_caused:\n                    caused.append(fid)\n            if caused:\n                _, detail, _ = sh(PYTEST.replace("-q", "-q --tb=short") + " " + " ".join(caused[:3]) +\n                                  " 2>&1 | grep -E \'^(E |>|[^ ].*:[0-9]+: )\' | head -24", ws, timeout=200)\n                if detail.strip():\n                    print("  why they fail:\\n    " + "\\n    ".join(l[:170] for l in detail.splitlines()))\n                print("  If a failing test\'s expected value is exactly the buggy behaviour the issue asks to change, "\n                      "that test is outdated (the maintainers update it): keep your fix. Otherwise fix your code.")\n    problems += ["fix failing test %s (or confirm it encodes the old buggy behaviour)" % c for c in caused]\n    siblings = sibling_sweep(ws)\n    if siblings:\n        print("\\nSAME CODE ELSEWHERE (you changed this code in one place; these copies may have the same bug):")\n        for n in siblings:\n            print("  " + n)\n        problems.append("check the SAME CODE ELSEWHERE list: apply the same fix there if it has the same bug")\n\n    print()\n    if repro is None and not problems:\n        print("note: no --repro given; for a behaviour change, verify with check.py --repro /tmp/repro.py")\n    if problems:\n        print("VERDICT: FIX BEFORE SUBMITTING")\n        for p in problems:\n            print("  - " + p)\n    else:\n        print("VERDICT: OK - make sure every requirement of the issue is implemented, then call submit_patch")\n\n\nif __name__ == "__main__":\n    main()\n', 'edit.py': '"""Replace a range of lines, reading the new lines from stdin (a quoted heredoc).\n\nusage:\n  python3 .swetools/edit.py FILE START END <<\'EOF\'\n  new line 1\n  new line 2\n  EOF\n\nReplaces lines START..END (inclusive, numbers from show.py) with the text\nbetween the EOF markers, exactly as written: no escaping is needed inside a\nquoted heredoc. END = START - 1 inserts before START without removing anything.\nAn empty heredoc deletes the lines.\n\nSafety: the edit is refused (file unchanged) when it would leave a Python\nsyntax error, or when the line numbers are stale because an earlier edit moved\nthe lines below it (view them again with show.py first).\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom _ws import digest, is_test_path, load_state, save_state, sh, warn_if_repeated, workspace  # noqa: E402\n\n\ndef _compile_error(text, rel):\n    try:\n        compile(text, rel, "exec")\n        return None\n    except SyntaxError as exc:\n        return exc\n\n\ndef _unescape(text):\n    return text.replace("\\\\n", "\\n").replace("\\\\t", "\\t").replace(\'\\\\"\', \'"\')\n\n\ndef _shift(block, delta):\n    out = []\n    for line in block:\n        if not line.strip():\n            out.append(line)\n        elif delta >= 0:\n            out.append(" " * delta + line)\n        else:\n            cut = min(-delta, len(line) - len(line.lstrip(" ")))\n            out.append(line[cut:])\n    return out\n\n\ndef _indent(line):\n    return len(line) - len(line.lstrip(" "))\n\n\ndef _module(rel):\n    p = rel[:-3]\n    for prefix in ("src/",):\n        if p.startswith(prefix):\n            p = p[len(prefix):]\n    p = p.replace("/", ".")\n    return p[:-9] if p.endswith(".__init__") else p\n\n\ndef main():\n    if len(sys.argv) < 4:\n        print(__doc__)\n        return\n    ws = workspace()\n    rel = sys.argv[1]\n    path = os.path.join(ws, rel)\n    if is_test_path(rel) or os.path.basename(rel) in ("conftest.py", "pytest.ini"):\n        sys.exit("error: do not edit test or pytest config files")\n    try:\n        start, end = int(sys.argv[2]), int(sys.argv[3])\n    except ValueError:\n        sys.exit("error: START and END must be line numbers")\n    try:\n        with open(path, encoding="utf-8") as fh:\n            old = fh.read()\n    except OSError as exc:\n        sys.exit("error: %s" % exc)\n    lines = old.split("\\n")\n    trailing = old.endswith("\\n")\n    if trailing:\n        lines = lines[:-1]\n    if not (1 <= start <= len(lines) + 1) or not (start - 1 <= end <= len(lines)):\n        sys.exit("error: file has %d lines; need 1 <= START <= END <= %d (or END = START-1 to insert)"\n                 % (len(lines), len(lines)))\n\n    state = load_state()\n    moved = state.get("moved", {}).get(rel)\n    if moved and start > moved[0]:\n        sys.exit("REFUSED, file unchanged: your earlier edit moved every line below line %d by %+d, so "\n                 "lines %d-%d are not the lines you think. Run show.py %s on that area first, then edit with "\n                 "the new numbers." % (moved[0], moved[1], start, end, rel))\n\n    new_text = "" if sys.stdin.isatty() else sys.stdin.read()\n    bad = [l for l in new_text.split("\\n") if re.match(r"\\s*EOF\\S", l) or l.strip() == "EOF"]\n    if bad:\n        sys.exit("REFUSED, file unchanged: the heredoc end marker is malformed (%r). The command must end with a "\n                 "line that is exactly EOF, with nothing after it." % bad[0].strip())\n    warn_if_repeated(sys.argv + [new_text, old])\n\n    def build(text):\n        nl = text.split("\\n")\n        if nl and nl[-1] == "":\n            nl = nl[:-1]\n        return nl\n\n    new_lines = build(new_text)\n    removed = lines[start - 1:end]\n    notes = []\n    if rel.endswith(".py"):\n        def result(nl):\n            return "\\n".join(lines[:start - 1] + nl + lines[end:]) + "\\n"\n        err = _compile_error(result(new_lines), rel)\n        if err is not None and "\\\\n" in new_text:\n            alt = build(_unescape(new_text))\n            if _compile_error(result(alt), rel) is None:\n                new_lines, err = alt, None\n                notes.append("note: your text had literal \\\\n sequences; decoded them so the file compiles")\n        if err is not None and new_lines:\n            anchor = next((l for l in removed if l.strip()), None) or next(\n                (l for l in reversed(lines[:start - 1]) if l.strip()), "")\n            first = next((l for l in new_lines if l.strip()), "")\n            delta = _indent(anchor) - _indent(first)\n            if 0 < abs(delta) <= 3:\n                alt = _shift(new_lines, delta)\n                if _compile_error(result(alt), rel) is None:\n                    new_lines, err = alt, None\n                    notes.append("note: shifted your lines by %+d spaces to match the code they replace" % delta)\n        if err is not None:\n            print("REFUSED, file unchanged: the edit would leave a syntax error at line %s: %s"\n                  % (err.lineno, err.msg))\n            lo = max(1, start - 2)\n            print("current lines %d-%d:" % (lo, min(len(lines), end + 2)))\n            for i in range(lo - 1, min(len(lines), end + 2)):\n                print("%5d| %s" % (i + 1, lines[i][:160]))\n            print("rewrite the whole block with correct indentation and balanced brackets, then run edit.py again")\n            sys.exit(1)\n\n    lines[start - 1:end] = new_lines\n    with open(path, "w", encoding="utf-8") as fh:\n        fh.write("\\n".join(lines) + ("\\n" if trailing else ""))\n    delta = len(new_lines) - len(removed)\n    moved_map = state.setdefault("moved", {})\n    if delta:\n        # Lines after the new block moved; the block itself was just printed with its new numbers.\n        prev = moved_map.get(rel)\n        edge = start + max(len(new_lines), 1) - 1\n        moved_map[rel] = [min(edge, prev[0]) if prev else edge, delta + (prev[1] if prev else 0)]\n    save_state(state)\n\n    for n in notes:\n        print(n)\n    print("replaced %d line(s) %d-%d with %d line(s)%s" % (\n        len(removed), start, end, len(new_lines),\n        "; lines below moved by %+d (view them again before editing there)" % delta if delta else ""))\n    if removed:\n        print("removed:")\n        for l in removed[:6]:\n            print("   - " + l[:160])\n        if len(removed) > 6:\n            print("   - ... (%d more)" % (len(removed) - 6))\n    lo, hi = max(1, start - 1), min(len(lines), start + len(new_lines))\n    shown = list(range(lo - 1, hi))\n    if len(shown) > 14:\n        shown = shown[:6] + [None] + shown[-6:]\n    for i in shown:\n        if i is None:\n            print("   ...")\n            continue\n        mark = ">" if start - 1 <= i < start - 1 + len(new_lines) else " "\n        print("%s%5d| %s" % (mark, i + 1, lines[i][:200]))\n    if rel.endswith(".py"):\n        mod = _module(rel)\n        if not mod.startswith(("docs_src", "scripts", "docs.", "tests")):\n            code, out, err = sh(["python3", "-c", "import " + mod], ws, timeout=60)\n            if code:\n                last = ((err or out).strip().splitlines() or ["?"])[-1]\n                print("syntax OK, but import %s now fails: %s" % (mod, last[:200]))\n            else:\n                print("syntax OK, import OK")\n        else:\n            print("syntax OK")\n\n\nif __name__ == "__main__":\n    main()\n', 'locate.py': '"""Rank the code most relevant to an issue.\n\nusage: python3 .swetools/locate.py TERM [TERM ...]\nTERMs are identifiers, option names, error messages or phrases from the issue,\ne.g.  locate.py strict_content_type "JSON requests" APIRouter "Content-Type"\n\nPrints the best-matching definitions (file:line, signature, why), exact text\nhits for each term, and the test files that exercise the top matches.\n"""\n\nimport ast\nimport math\nimport os\nimport re\nimport sys\nfrom collections import Counter, defaultdict\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom _ws import is_test_path, tracked_py, workspace, warn_if_repeated  # noqa: E402\n\nWORD = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")\n\n\ndef subtokens(word):\n    parts = re.sub(r"([a-z0-9])([A-Z])", r"\\1_\\2", word).lower().split("_")\n    return [p for p in parts if len(p) > 2]\n\n\ndef defs_in(path, text):\n    try:\n        tree = ast.parse(text)\n    except (SyntaxError, ValueError):\n        return []\n    lines = text.splitlines()\n    out = []\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            end = getattr(node, "end_lineno", node.lineno) or node.lineno\n            body = "\\n".join(lines[node.lineno - 1:end])\n            out.append((node.name, node.lineno, end, lines[node.lineno - 1].strip(), body))\n    return out\n\n\ndef main():\n    warn_if_repeated(sys.argv)\n    terms = [t for t in sys.argv[1:] if t.strip()]\n    if not terms:\n        print(__doc__)\n        return\n    # "padding width" -> padding_width / paddingWidth, so phrases also match identifiers.\n    for t in list(terms):\n        words = re.findall(r"[A-Za-z][A-Za-z0-9]*", t)\n        if 2 <= len(words) <= 3 and " " in t.strip():\n            snake = "_".join(w.lower() for w in words)\n            camel = words[0].lower() + "".join(w.capitalize() for w in words[1:])\n            for v in (snake, camel):\n                if v not in terms:\n                    terms.append(v)\n    ws = workspace()\n    files = tracked_py(ws)\n    src = [f for f in files if not is_test_path(f)]\n    tests = [f for f in files if is_test_path(f) and os.path.basename(f) != "conftest.py"]\n\n    idents = [t for t in terms if WORD.fullmatch(t)]\n    phrases = [t for t in terms if not WORD.fullmatch(t)]\n    toks = Counter()\n    for t in terms:\n        for w in WORD.findall(t):\n            for s in subtokens(w):\n                toks[s] += 1\n\n    texts = {}\n    for f in src:\n        try:\n            with open(os.path.join(ws, f), encoding="utf-8", errors="replace") as fh:\n                texts[f] = fh.read()\n        except OSError:\n            pass\n\n    # Inverse document frequency over definitions for sub-tokens.\n    all_defs = []\n    df = Counter()\n    for f, text in texts.items():\n        for d in defs_in(f, text):\n            all_defs.append((f,) + d)\n            words = set(s for w in WORD.findall(d[4]) for s in subtokens(w))\n            for s in toks:\n                if s in words:\n                    df[s] += 1\n    n = max(1, len(all_defs))\n\n    scored = []\n    for f, name, start, end, sig, body in all_defs:\n        score, why = 0.0, []\n        low_name = name.lower()\n        for ident in idents:\n            li = ident.lower()\n            if li == low_name:\n                score += 12; why.append("defines " + ident)\n            elif li in low_name:\n                score += 5; why.append("name~" + ident)\n            c = body.count(ident)\n            if c:\n                score += 3 + math.log1p(c); why.append("%s x%d" % (ident, c))\n        low_body = body.lower()\n        for ph in phrases:\n            if ph.lower() in low_body:\n                score += 6; why.append(\'"%s"\' % ph[:30])\n        body_words = Counter(s for w in WORD.findall(body) for s in subtokens(w))\n        for s in toks:\n            if body_words[s]:\n                score += math.log(1 + n / (1 + df[s])) * (0.4 + 0.15 * math.log1p(body_words[s]))\n        for s in toks:\n            if s in f.lower():\n                score += 0.8\n        # Prefer focused definitions over whole classes / huge functions.\n        score /= 1 + 0.35 * math.log1p(max(0, end - start - 60))\n        if f.startswith(("docs_src/", "docs/", "examples/", "scripts/")):\n            score *= 0.5\n        if score > 0:\n            scored.append((score, f, start, end, sig, why))\n    scored.sort(key=lambda x: -x[0])\n\n    print("TOP DEFINITIONS (file:line-end  signature  [why])")\n    shown, per_file = 0, Counter()\n    for score, f, start, end, sig, why in scored:\n        if per_file[f] >= 3:\n            continue\n        per_file[f] += 1\n        shown += 1\n        print("%2d. %s:%d-%d  %s  [%s]" % (shown, f, start, end, sig[:110], ", ".join(why[:4])))\n        if shown >= 12:\n            break\n\n    print("\\nEXACT TEXT HITS (first 4 per term, library code first)")\n    ordered = sorted(src, key=lambda f: f.startswith(("docs_src/", "docs/", "examples/", "scripts/")))\n    for t in terms:\n        hits = []\n        needle = t if WORD.fullmatch(t) else t.lower()\n        for f in ordered:\n            text = texts.get(f, "")\n            hay = text if WORD.fullmatch(t) else text.lower()\n            if needle in hay:\n                for i, line in enumerate(hay.splitlines(), 1):\n                    if needle in line:\n                        hits.append("%s:%d" % (f, i))\n                        if len(hits) >= 4:\n                            break\n            if len(hits) >= 4:\n                break\n        print(\'  "%s": %s\' % (t[:40], ", ".join(hits) if hits else "no match in source"))\n\n    top_names = []\n    for score, f, start, end, sig, why in scored[:8]:\n        m = re.match(r"(?:async\\s+)?(?:def|class)\\s+(\\w+)", sig)\n        if m and m.group(1) not in top_names and not m.group(1).startswith("__"):\n            top_names.append(m.group(1))\n    top_mods = set(os.path.splitext(os.path.basename(f))[0] for _, f, *_ in scored[:8])\n    test_hits = defaultdict(int)\n    for t in tests:\n        try:\n            with open(os.path.join(ws, t), encoding="utf-8", errors="replace") as fh:\n                text = fh.read()\n        except OSError:\n            continue\n        for name in top_names + idents:\n            if name in text:\n                test_hits[t] += text.count(name)\n        base = os.path.basename(t)\n        for mod in top_mods:\n            if base in ("test_%s.py" % mod, "%s_test.py" % mod):\n                test_hits[t] += 20\n    print("\\nTEST FILES FOR THIS CODE (hidden tests usually go into one of these)")\n    ranked = sorted(test_hits.items(), key=lambda kv: -kv[1])[:6]\n    print("  " + (", ".join("%s" % t for t, _ in ranked) if ranked else "none found"))\n\n\nif __name__ == "__main__":\n    main()\n', 'run.py': '"""Run a Python script from /tmp against the repository.\n\nusage: python3 .swetools/run.py /tmp/script.py\n\nRuns the script (timeout 90 s) and prints the last 30 lines of its output with\nthe exit code. If neither the script nor the repository changed since an\nearlier run, it does not run again: it repeats the earlier result, because the\nanswer cannot be different. Change the script or the code first.\n"""\n\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom _ws import digest, load_state, save_state, sh, workspace  # noqa: E402\n\n\ndef main():\n    if len(sys.argv) < 2:\n        print(__doc__)\n        return\n    ws = workspace()\n    script = sys.argv[1]\n    try:\n        with open(script, encoding="utf-8", errors="replace") as fh:\n            body = fh.read()\n    except OSError as exc:\n        sys.exit("error: %s (write the script first, e.g. cat > /tmp/x.py <<\'EOF\' ... EOF)" % exc)\n    _, diff, _ = sh(["git", "diff", "HEAD"], ws)\n    key = digest(body, diff)\n    state = load_state()\n    runs = state.setdefault("runs", {})\n    if key in runs:\n        prev = runs[key]\n        print("SAME SCRIPT, SAME CODE as run #%d, so the result is the same (not run again):" % prev["n"])\n        print(prev["out"])\n        print("Change the script or the code before running it again.")\n        return\n    code, out, err = sh(["bash", "-c", "timeout 90 python3 -B %s 2>&1 | tail -30; exit ${PIPESTATUS[0]}" % script],\n                        ws, timeout=120)\n    text = (out or err or "").rstrip() or "(no output)"\n    text += "\\n[exit code %d]" % code\n    print(text)\n    runs[key] = {"n": len(runs) + 1, "out": text[-1500:]}\n    save_state(state)\n\n\nif __name__ == "__main__":\n    main()\n', 'show.py': '"""Show numbered lines of a file.\n\nusage: python3 .swetools/show.py FILE START [END]     (at most 40 lines)\n       python3 .swetools/show.py FILE /regex/          (every matching line, numbered)\nThe numbers are what edit.py expects.\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom _ws import digest, load_state, save_state, workspace  # noqa: E402\n\n\ndef main():\n    if len(sys.argv) < 3:\n        print(__doc__)\n        return\n    path = os.path.join(workspace(), sys.argv[1])\n    try:\n        with open(path, encoding="utf-8", errors="replace") as fh:\n            lines = fh.read().split("\\n")\n    except OSError as exc:\n        sys.exit("error: %s" % exc)\n    state = load_state()\n    rel = sys.argv[1]\n    key = digest(*(sys.argv[1:] + ["\\n".join(lines)]))\n    seen = state.setdefault("shown", [])\n    moved = state.get("moved", {})\n    if rel in moved:\n        del moved[rel]\n    if key in seen:\n        save_state(state)\n        print("UNCHANGED: you already viewed exactly these lines and the file has not changed since, so they "\n              "are not printed again. Use what you read, or view a different range.")\n        return\n    seen.append(key)\n    save_state(state)\n    arg = sys.argv[2]\n    if arg.startswith("/") and arg.endswith("/") and len(arg) > 1:\n        pat = re.compile(arg[1:-1])\n        hits = [i for i, l in enumerate(lines) if pat.search(l)][:25]\n        for i in hits:\n            print("%5d| %s" % (i + 1, lines[i]))\n        if not hits:\n            print("no match")\n        return\n    start = max(1, int(arg))\n    end = int(sys.argv[3]) if len(sys.argv) > 3 else start + 39\n    end = min(end, start + 39, len(lines))\n    for i in range(start - 1, end):\n        print("%5d| %s" % (i + 1, lines[i][:200]))\n    if end < len(lines):\n        print("  ... (%d lines in file)" % len(lines))\n\n\nif __name__ == "__main__":\n    main()\n'}
MAPS = {'fastapi': 'FASTAPI ARCHITECTURE MAP (verified at commit f1d750fd; notes on older checkouts at the end)\n\n1. PACKAGE LAYOUT (fastapi/)\n- applications.py: class FastAPI(Starlette). Holds self.router (an APIRouter), exception_handlers, build_middleware_stack, openapi(), setup() (adds /openapi.json, /docs, /redoc routes). Its get/post/add_api_route/include_router/websocket methods just delegate to self.router.\n- routing.py: APIRoute, APIWebSocketRoute, APIRouter, get_request_handler, get_websocket_app, serialize_response, run_endpoint_function, request_response, websocket_session, _populate_api_route_state, include machinery (_RouterIncludeContext, _IncludedRouter, _EffectiveRouteContext, RouteContext, iter_route_contexts).\n- dependencies/models.py: dataclass Dependant (path_params, query_params, header_params, cookie_params, body_params, dependencies, call, request_param_name, response_param_name, use_cache, scope, cache_key ...).\n- dependencies/utils.py: get_dependant, analyze_param, add_param_to_fields, get_flat_dependant, get_typed_signature, solve_dependencies, request_params_to_args, request_body_to_args, get_body_field, _should_embed_body_fields.\n- params.py: FieldInfo subclasses Param (Path, Query, Header, Cookie) and Body (Form, File), plus Depends and Security dataclasses. param_functions.py: the public functions Path(), Query(), Header(), Cookie(), Body(), Form(), File(), Depends(), Security() that build those classes (same parameter lists, documented with Annotated[..., Doc(...)]).\n- _compat/: __init__.py re-exports; shared.py (lenient_issubclass, field_annotation_is_scalar, is_uploadfile..., annotation_is_pydantic_v1); v2.py (ModelField dataclass wrapping a TypeAdapter with validate/serialize/serialize_json, get_definitions, get_schema_from_model_field, create_body_model, get_missing_field_error, Undefined, RequiredParam).\n- openapi/utils.py: get_openapi, get_openapi_path, _get_openapi_operation_parameters, get_openapi_operation_request_body, get_openapi_security_definitions, generate_operation_id, generate_operation_summary, get_fields_from_routes, validation_error_definition. openapi/models.py: pydantic models of the OpenAPI document. openapi/docs.py: get_swagger_ui_html, get_redoc_html, get_swagger_ui_oauth2_redirect_html. openapi/constants.py: REF_PREFIX etc.\n- exceptions.py: HTTPException, WebSocketException, FastAPIError(RuntimeError), DependencyScopeError, ValidationException, RequestValidationError, WebSocketRequestValidationError, ResponseValidationError, PydanticV1NotSupportedError, FastAPIDeprecationWarning, EndpointContext.\n- exception_handlers.py: http_exception_handler, request_validation_exception_handler (422 with detail=jsonable_encoder(exc.errors())), websocket_request_validation_exception_handler.\n- encoders.py: jsonable_encoder, ENCODERS_BY_TYPE, decimal_encoder. utils.py: is_body_allowed_for_status_code, get_path_param_names, create_model_field, generate_unique_id, deep_dict_update, get_value_or_default.\n- datastructures.py: UploadFile, DefaultPlaceholder, Default(). security/: base.py SecurityBase, api_key.py, http.py (HTTPBasic, HTTPBearer, HTTPDigest), oauth2.py, open_id_connect_url.py; each scheme is a callable class with async __call__(request) and make_not_authenticated_error.\n- sse.py: EventSourceResponse, ServerSentEvent, format_sse_event. middleware/asyncexitstack.py: AsyncExitStackMiddleware. responses.py, requests.py, websockets.py, testclient.py, staticfiles.py, templating.py mostly re-export Starlette.\n\n2. DATA FLOWS\nRoute creation: app.get(...) -> APIRouter.api_route/get -> APIRouter.add_api_route merges router-level options (prefix, tags, dependencies, responses, callbacks, deprecated, include_in_schema, default_response_class, generate_unique_id_function, strict_content_type) with the route arguments, then route_class(...) -> APIRoute.__init__ -> _populate_api_route_state. That function infers response_model from the return annotation when response_model is Default, builds response_field via create_model_field, computes unique_id, builds route.dependant = get_dependant(...), prepends router dependencies with get_parameterless_sub_dependant, computes _flat_dependant, _embed_body_fields and body_field (get_body_field). Then self.app = request_response(self.get_route_handler()).\nParameter analysis: get_dependant iterates get_typed_signature(call).parameters; analyze_param decides per parameter: Annotated metadata or default value gives FieldInfo or Depends; Request/WebSocket/Response/BackgroundTasks/SecurityScopes are special (add_non_field_param_to_dependency); otherwise path name -> Path, UploadFile -> File, non-scalar -> Body, else Query. Header aliases convert underscores to hyphens. Sub-dependencies recurse through get_dependant. Invalid combinations raise AssertionError with a message.\nRequest handling: APIRoute.handle -> get_request_handler(...).app(request): reads body (form via request.form(), JSON if content-type is json or +json, strict_content_type), JSON errors become RequestValidationError(type json_invalid); solve_dependencies resolves sub-dependencies (cache via dependency_cache and cache_key, dependency_overrides_provider.dependency_overrides, yield dependencies on AsyncExitStacks in scope keys fastapi_inner_astack / fastapi_function_astack), then request_params_to_args for path/query/header/cookie and request_body_to_args for body. Errors -> RequestValidationError. Otherwise run_endpoint_function (threadpool for sync def) -> serialize_response (response_field.validate then serialize or serialize_json; ResponseValidationError on failure; jsonable_encoder when no field) -> response_class(content, status_code, background). Generator endpoints stream as JSONL or SSE. Body is emptied when is_body_allowed_for_status_code is False. Websockets: APIWebSocketRoute -> get_websocket_app -> solve_dependencies -> WebSocketRequestValidationError.\nOption threading: defaults use Default(value) (a DefaultPlaceholder); get_value_or_default(first, *rest) returns the first non-placeholder. include_router at this commit is lazy: it appends an _IncludedRouter(original_router, _RouterIncludeContext) instead of copying routes; _RouterIncludeContext.combine merges nested includes (prefix concat, tags/dependencies/callbacks concatenated, responses dict-merged, deprecated or-ed, include_in_schema and-ed, response class and unique id via get_value_or_default); _EffectiveRouteContext.from_api_route produces the per-include effective route values used for matching, handling and OpenAPI; consumers iterate routes with iter_route_contexts.\nOpenAPI: FastAPI.openapi() caches get_openapi(...) keyed on router._get_routes_version(); get_openapi collects fields (get_fields_from_routes), get_definitions, then get_openapi_path per route context builds parameters, requestBody, responses (adds 422 HTTPValidationError when there are params or a body), security, callbacks; the result is jsonable_encoder(OpenAPI(**output), by_alias=True, exclude_none=True).\nErrors: FastAPI.__init__ registers default handlers with exception_handlers.setdefault; build_middleware_stack puts ServerErrorMiddleware, user middleware, ExceptionMiddleware, AsyncExitStackMiddleware around self.router.\n\n3. WHERE CHANGES GO\n- New route/router option: add to APIRoute.__init__, _populate_api_route_state, _APIRouteLike, APIRouter.__init__/add_api_route/api_route and every verb method (get, put, post, delete, options, head, patch, trace), FastAPI verb methods and add_api_route, and include-level merging (_RouterIncludeContext, _EffectiveRouteContext) if it can be set per router.\n- New parameter option: params.py class plus matching param_functions.py function; analysis in analyze_param; OpenAPI in _get_openapi_operation_parameters.\n- Validation/error messages: dependencies/utils.py, exceptions.py, exception_handlers.py, _compat/v2.py (_regenerate_error_with_loc, get_missing_field_error).\n- Serialization: serialize_response, jsonable_encoder, ModelField.serialize.\n- OpenAPI output: openapi/utils.py and openapi/models.py. Security schemes: fastapi/security/.\n\n4. CONVENTIONS\n- Internal invariants use assert with a message; user-facing config errors raise FastAPIError; HTTP errors raise HTTPException(status_code, detail, headers).\n- Keyword-only args, modern typing (X | None, list[...]), Annotated[..., Doc("...")] documentation on public signatures.\n- Tests in tests/, flat files test_*.py; they build a small FastAPI() app, use fastapi.testclient.TestClient(app), assert response.status_code and response.json(), and often compare app.openapi() or client.get("/openapi.json").json() with inline_snapshot snapshot(...). Tutorial code lives in docs_src/<topic>/tutorialNNN_py310.py with tests in tests/test_tutorial/test_<topic>/ importing the module via importlib and a parametrized client fixture; markers needs_py310 etc. live in tests/utils.py.\n\n5. PITFALLS\n- Sync def endpoints/dependencies run in a threadpool; async ones are awaited; generators vs async generators differ (is_gen_callable, is_async_gen_callable).\n- HTTP and websocket paths are separate (get_request_handler vs get_websocket_app, APIRoute vs APIWebSocketRoute, separate exception handlers).\n- Router-level vs app-level vs include_router-level options merge differently; check both add_api_route and the include context code.\n- Default() placeholders are truthy/falsy by value; test with isinstance(x, DefaultPlaceholder), not truthiness.\n- analyze_param copies FieldInfo before mutating; do not mutate shared FieldInfo/Depends objects.\n- OpenAPI schema is cached; mode "validation" vs "serialization" schemas differ (separate_input_output_schemas).\n- Older checkouts (around 2025) differ: fastapi/_compat.py is a single module with PYDANTIC_V2 branches (keep v1 and v2 branches in sync), include_router eagerly copies each route by calling self.add_api_route/add_api_websocket_route with merged values, and Python 3.8 syntax (Optional, List) is required.\n', 'httpx': 'HTTPX ARCHITECTURE MAP (verified at commit 4acf5c2c, the 1.0 development rewrite)\n\nIMPORTANT: at this commit httpx is NOT the classic 0.x layout (no httpx/_client.py with AsyncClient, no _models.py, no _transports/, no httpcore). It is a small self-contained rewrite with its own HTTP/1.1 parser, network layer and server.\n\n1. LAYOUT\n- src/ahttpx/: the async source of truth. src/httpx/: the sync package, generated from ahttpx by scripts/unasync (unasync rules rewrite ahttpx -> httpx and async/await to sync). Both trees are committed.\n- _client.py: Client(url, headers, transport) with build_request, request, stream, get, post, put, patch, delete, close; RedirectMiddleware(Transport) with is_redirect, build_redirect_request, send.\n- _pool.py: Transport base (send, close, request, stream), ConnectionPool (send, _get_connection, _cleanup, connections, description), Connection (send, _send_head, _send_body, _recv_head, _recv_body, _complete), open_connection.\n- _parsers.py: HTTPParser state machine (send_method_line, send_status_line, send_headers, send_body, recv_method_line, recv_status_line, recv_headers, recv_body, complete), ReadAheadParser, ProtocolError, State, Mode, bounded_int, bounded_hex.\n- _network.py: NetworkBackend (connect, connect_tls, listen, serve), NetworkStream, NetworkListener, NetworkServer, timeout, get_current_timeout.\n- _server.py: HTTPServer, HTTPConnection, serve_http, run (used by tests as a local echo server).\n- _request.py: Request(method, url, headers, content) with body, read, close. _response.py: Response(status_code, headers, content) with reason_phrase, body, text, read, close.\n- _headers.py: Headers (immutable-style API: copy_set, copy_remove, copy_update, get, items), headername, headervalue, parse_opts_header.\n- _urls.py: URL (scheme, userinfo, host, port, path, query, params, target, fragment, copy_with, copy_set_param, copy_append_param, copy_remove_param, copy_merge_params, join) and QueryParams (copy_set, copy_append, copy_remove, copy_update, get_list, multi_items). _urlparse.py: urlparse, ParseResult, InvalidURL, encode_host, normalize_port, validate_path, normalize_path, quote, percent_encoded. _urlencode.py: urlencode, urldecode, quote, unquote, percent.\n- _content.py: Content base (encode, content_type) and Form, File, Files, JSON, Text, HTML, MultiPart. _streams.py: Stream, ByteStream, DuplexStream, FileStream, HTTPStream, MultiPartStream.\n- _quickstart.py: module-level get, post, put, patch, delete. __init__.py re-exports the public names.\n\n2. FLOW\nhttpx.get(url) or Client.request -> build_request (self.url.join(url), self.headers.copy_update(headers), Content/Stream/bytes) -> RedirectMiddleware.send -> ConnectionPool.send -> Connection.send writes head/body through HTTPParser over a NetworkStream, reads status line, headers and body into a Response with an HTTPStream -> Client.request calls response.read() inside a with block; Client.stream returns the open response.\n\n3. WHERE CHANGES GO\n- URL parsing/encoding: _urlparse.py (validation raises InvalidURL) and _urls.py (URL/QueryParams API); percent helpers in _urlencode.py.\n- Header behavior: _headers.py. Body encoding and content types: _content.py and _streams.py.\n- Wire protocol: _parsers.py. Connection reuse: _pool.py. Redirects: RedirectMiddleware in _client.py.\n- Make every change in src/ahttpx first and mirror it exactly (sync form) in src/httpx, or both packages drift; _network.py is not in the unasync list and is maintained separately in each tree.\n\n4. CONVENTIONS AND TESTS\n- Immutable-style models: methods named copy_* return new objects instead of mutating.\n- Type hints with X | None; mypy runs on both src/httpx and src/ahttpx (scripts/test).\n- Tests in tests/test_<module>.py target the sync httpx package only: pytest fixtures create httpx.Client() and httpx.serve_http(handler) servers; unit tests construct httpx.URL, httpx.Headers, httpx.QueryParams, httpx.Request/Response directly and assert on str(), repr(), .body, .text.\n\n5. PITFALLS\n- Do not look for or recreate the 0.x API (AsyncClient, Timeout, Limits, codes, HTTPStatusError); it does not exist here.\n- repr() output is asserted in tests; keep formats stable.\n- Async and sync trees must stay in sync; tests only exercise httpx.\n', 'requests': 'REQUESTS ARCHITECTURE MAP (verified at commit 6f205ff4; notes on older checkouts at the end)\n\n1. PACKAGE LAYOUT (src/requests/, imported as requests)\n- api.py: module functions request, get, options, head, post, put, patch, delete. Each opens a sessions.Session() in a with block and calls session.request(method, url, **kwargs).\n- sessions.py: merge_setting, merge_hooks, SessionRedirectMixin (get_redirect_target, should_strip_auth, resolve_redirects, rebuild_auth, rebuild_proxies, rebuild_method), Session (headers, auth, proxies, hooks, params, stream, verify, cert, max_redirects, trust_env, cookies, adapters; prepare_request, request, send, merge_environment_settings, get_adapter, mount, close), session().\n- models.py: RequestEncodingMixin (path_url, _encode_params, _encode_files), RequestHooksMixin, Request (user-level description, prepare()), PreparedRequest (prepare, prepare_method, prepare_url, prepare_headers, prepare_cookies, prepare_body, prepare_content_length, prepare_auth, prepare_hooks, copy), Response (content, text, json, iter_content, iter_lines, links, ok, is_redirect, is_permanent_redirect, next, apparent_encoding, raise_for_status, close). Constants REDIRECT_STATI, DEFAULT_REDIRECT_LIMIT, CONTENT_CHUNK_SIZE, ITER_CHUNK_SIZE.\n- adapters.py: BaseAdapter, HTTPAdapter (init_poolmanager, proxy_manager_for, cert_verify, build_response, build_connection_pool_key_attributes, get_connection_with_tls_context, request_url, add_headers, proxy_headers, send). Talks to urllib3.\n- utils.py: helpers: super_len, get_netrc_auth, guess_filename, to_key_val_list, parse_list_header, parse_dict_header, unquote_header_value, get_encoding_from_headers, _parse_content_type_header, stream_decode_response_unicode, iter_slices, requote_uri, unquote_unreserved, should_bypass_proxies, get_environ_proxies, select_proxy, resolve_proxies, default_user_agent, default_headers, parse_header_links, guess_json_utf, prepend_scheme_if_needed, get_auth_from_url, check_header_validity, urldefragauth, rewind_body.\n- auth.py: _basic_auth_str, AuthBase, HTTPBasicAuth, HTTPProxyAuth, HTTPDigestAuth (build_digest_header, handle_401, handle_redirect, per-thread state).\n- cookies.py: MockRequest/MockResponse adapters for http.cookiejar, extract_cookies_to_jar, get_cookie_header, RequestsCookieJar, create_cookie, morsel_to_cookie, cookiejar_from_dict, merge_cookies.\n- structures.py: CaseInsensitiveDict (used for all headers), LookupDict. status_codes.py: _codes table turned into codes = LookupDict(...) (codes.ok, codes.temporary_redirect ...).\n- exceptions.py: RequestException(IOError) with request/response kwargs; HTTPError, ConnectionError, ProxyError, SSLError, Timeout, ConnectTimeout, ReadTimeout, URLRequired, TooManyRedirects, MissingSchema, InvalidSchema, InvalidURL, InvalidHeader, InvalidProxyURL, ChunkedEncodingError, ContentDecodingError, StreamConsumedError, RetryError, UnrewindableBodyError, InvalidJSONError, JSONDecodeError; warnings RequestsWarning, FileModeWarning, RequestsDependencyWarning.\n- compat.py: urllib/http.cookiejar re-exports, chardet resolution, is_urllib3_1, builtin_str, basestring, JSON library selection. _internal_utils.py: to_native_string, unicode_is_ascii. hooks.py: default_hooks, dispatch_hook (only the "response" event). _types.py: typing helpers (is_prepared, HookType). help.py, certs.py, packages.py.\n\n2. DATA FLOWS\nRequest: requests.get -> api.request -> Session.request builds Request(method.upper(), url, headers, files, data, json, params, auth, cookies, hooks) -> Session.prepare_request merges session and request settings (cookies via merge_cookies, headers via merge_setting with CaseInsensitiveDict, params, auth, hooks; netrc auth via get_netrc_auth when trust_env) -> PreparedRequest.prepare calls in order prepare_method, prepare_url, prepare_headers, prepare_cookies, prepare_body, prepare_auth, prepare_hooks -> Session.merge_environment_settings (env proxies, REQUESTS_CA_BUNDLE/CURL_CA_BUNDLE, verify, stream, cert) -> Session.send.\nprepare_url: decodes bytes, leaves non-http schemes untouched, parse_url from urllib3 (LocationParseError -> InvalidURL), MissingSchema if no scheme, InvalidURL if no host, IDNA-encode non-ASCII hosts (_get_idna_encoded_host), merge params via _encode_params, then requote_uri(urlunparse(...)).\nprepare_headers: CaseInsensitiveDict, each header checked by check_header_validity (InvalidHeader), name via to_native_string. prepare_body: json -> complexjson dumps and application/json; files -> _encode_files multipart; data dict -> form urlencoded; streams/generators -> chunked or Content-Length via super_len; prepare_content_length. prepare_auth: tuple -> HTTPBasicAuth, then calls auth(self).\nSession.send: get_adapter(url) by longest mounted prefix -> HTTPAdapter.send: get_connection_with_tls_context, cert_verify, request_url, add_headers, timeout to urllib3 Timeout (TimeoutSauce), conn.urlopen; urllib3 errors mapped to requests exceptions (ProtocolError/OSError -> ConnectionError, MaxRetryError -> ConnectTimeout/RetryError/ProxyError/SSLError/ConnectionError, ReadTimeoutError -> ReadTimeout) -> build_response creates Response (status, headers as CaseInsensitiveDict, encoding from get_encoding_from_headers, cookies, url, raw). Back in Session.send: elapsed, dispatch_hook("response"), extract_cookies_to_jar, resolve_redirects when allow_redirects, history, optional content read when not stream.\nRedirects: SessionRedirectMixin.resolve_redirects loops while get_redirect_target(resp): enforces max_redirects (TooManyRedirects), handles relative and scheme-less Location, copies the request, rebuild_method (303 and 302 become GET unless HEAD; 301 turns POST into GET), drops body headers except for 307/308, updates cookies, rebuild_proxies, rebuild_auth (strips Authorization when should_strip_auth says host/scheme changed), rewind_body, then send again.\nResponse reading: iter_content -> raw.stream / generator with decoding errors mapped to ChunkedEncodingError/ContentDecodingError; text uses encoding or apparent_encoding (chardet/charset_normalizer); json falls back via guess_json_utf and raises requests JSONDecodeError; raise_for_status builds "4xx Client Error"/"5xx Server Error" HTTPError.\n\n3. WHERE CHANGES GO\n- URL or param handling: PreparedRequest.prepare_url, RequestEncodingMixin._encode_params, utils.requote_uri/prepend_scheme_if_needed/urldefragauth.\n- Header handling: prepare_headers, utils.check_header_validity, structures.CaseInsensitiveDict, utils.default_headers.\n- Body/encoding: prepare_body, _encode_files, super_len, Response.text/json, utils.get_encoding_from_headers.\n- Redirect/auth behavior: sessions.SessionRedirectMixin, auth.py.\n- Proxy/env: utils.should_bypass_proxies, get_environ_proxies, resolve_proxies, Session.merge_environment_settings, adapters.proxy_manager_for.\n- Transport and error mapping: adapters.HTTPAdapter.send / build_response.\n- New exception: exceptions.py, subclassing the closest existing class (often also ValueError or the matching builtin) so old except clauses still catch it.\n- User-visible changes get a line under dev in HISTORY.md.\n\n4. CONVENTIONS\n- Raise requests exceptions with request=/response= kwargs when available; plain ValueError/TypeError for programmer misuse; assert only for internal invariants.\n- Defaults are None and resolved with merge_setting (request value wins, None in request removes a session key).\n- Headers are native str; bytes header values are allowed; use to_native_string.\n- Tests: tests/test_requests.py (class TestRequests etc.) uses the httpbin fixture from pytest-httpbin (conftest.py wraps it as httpbin("path")); tests/test_utils.py for pure helpers with pytest.mark.parametrize; tests/test_lowlevel.py uses tests/testserver/server.Server for raw socket responses; tests/test_structures.py, test_hooks.py, test_adapters.py. conftest clears proxy env vars. Many tests just call requests.Request(...).prepare() and inspect url/headers/body without network.\n\n5. PITFALLS\n- Both Request and PreparedRequest exist; Session.prepare_request vs Request.prepare differ in session merging (cookies, auth, headers).\n- CaseInsensitiveDict preserves the last-set key casing; merging uses lower_items.\n- Bytes vs str for URLs, headers, and bodies (to_native_string, builtin_str); URL already percent-encoded must not be double-encoded (requote_uri).\n- Redirect handling mutates a copy of the request; body and auth need rewinding/stripping; 307/308 keep method and body.\n- urllib3 1.x vs 2.x behavior (compat.is_urllib3_1) and chardet vs charset_normalizer.\n- Environment variables (proxies, NETRC, CA bundle) only apply when trust_env is True.\n- Older checkouts (late 2023) also use src/requests but without type annotations or _types.py, and support older Python versions; do not add annotations there.\n', 'rich': 'RICH ARCHITECTURE MAP (verified at commit 19c67b9a; notes on older checkouts at the end)\n\n1. PACKAGE LAYOUT (rich/)\n- console.py: Console (print, log, out, render, render_lines, render_str, get_style, measure, capture, export_text/html/svg, print_exception, _check_buffer, _render_buffer), ConsoleOptions (max_width, min_width, height, justify, overflow, no_wrap, highlight, markup; update, update_width, copy, reset_height), ConsoleDimensions, Capture, Group, RenderHook, detect_legacy_windows.\n- segment.py: Segment(text, style, control) NamedTuple plus classmethods apply_style, split_lines, split_and_crop_lines, adjust_line_length, get_line_length, get_shape, set_shape, simplify, divide, split_cells, strip_styles; Segments, SegmentLines.\n- text.py: Text (mutable plain string plus list of Span(start, end, style)); from_markup, from_ansi, assemble, styled, stylize, append, highlight_regex, render, wrap, divide, split, truncate, pad, align, expand_tabs, fit, cell_len, __rich_console__, __rich_measure__.\n- style.py: Style (color, bgcolor, bold, dim, italic, underline, link, meta ...), Style.parse, combine, chain, __add__, render, null; StyleStack. color.py: Color, ColorSystem, ColorType, ColorParseError, downgrade logic. color_triplet.py, palette.py, _palettes.py.\n- theme.py: Theme, ThemeStack; default_styles.py: DEFAULT_STYLES dict; themes.py: DEFAULT = Theme(DEFAULT_STYLES).\n- markup.py: Tag, escape, render (parses [style]text[/style] into Text; MarkupError on bad closing tags). emoji.py/_emoji_replace.py for :name: codes.\n- cells.py: cell_len, cached_cell_len, get_character_cell_size, set_cell_size, chop_cells, split_graphemes (tables in _unicode_data/). _wrap.py: words, divide_line (cell-based word wrap used by Text.wrap).\n- measure.py: Measurement(minimum, maximum), Measurement.get(console, options, renderable), normalize, clamp, with_maximum; measure_renderables.\n- Layout renderables: table.py (Table, Column, Row, add_column, add_row, add_section, _calculate_column_widths, _collapse_widths, _measure_column, _render), box.py (Box and constants like ROUNDED, SQUARE, ASCII), panel.py (Panel, Panel.fit), padding.py (Padding, Padding.unpack), columns.py, align.py, constrain.py, rule.py, tree.py, layout.py, styled.py, containers.py (Renderables, Lines), _ratio.py (ratio_resolve, ratio_reduce, ratio_distribute).\n- Content renderables: syntax.py (Syntax via pygments), markdown.py (Markdown via markdown-it), pretty.py (Pretty, traverse, pretty_repr, pprint, install), json.py, highlighter.py (RegexHighlighter, ReprHighlighter, JSONHighlighter), ansi.py (AnsiDecoder).\n- traceback.py: install, Traceback (from_exception, extract -> Trace/Stack/Frame dataclasses, __rich_console__, _render_stack, _render_syntax_error).\n- Dynamic: live.py (Live with _RefreshThread, uses live_render.LiveRender and console.set_live), progress.py (Progress, Task, ProgressColumn subclasses like BarColumn, TextColumn, TimeRemainingColumn, track, wrap_file, open), progress_bar.py, spinner.py, status.py.\n- logging.py: RichHandler(logging.Handler) with emit -> render_message -> render (uses _log_render.LogRender).\n- prompt.py: Prompt, IntPrompt, FloatPrompt, Confirm. errors.py: ConsoleError, StyleError, StyleSyntaxError, MissingStyle, NotRenderableError, MarkupError, LiveError. protocol.py: is_renderable, rich_cast. __init__.py: get_console, print, print_json, inspect, reconfigure.\n\n2. DATA FLOWS\nPrinting: Console.print(*objects, style, justify, overflow, no_wrap, markup, highlight, width, ...) -> _collect_renderables (strings go through render_str -> markup.render or Text, plus highlighter) -> ConsoleOptions.update(...) -> Console.render(renderable, options) which calls renderable.__rich_console__(console, options) recursively until only Segment objects remain -> Segment.apply_style -> appended to the thread-local buffer -> _check_buffer -> _render_buffer turns segments into text with Style.render (ANSI codes for the active color_system) -> file.write. record=True keeps segments for export_*.\nRenderables that wrap others (Panel, Padding, Table cells) call console.render_lines(child, options.update(width=...)) to get a list of lines of Segments already cropped/padded to width, then decorate them. Width negotiation uses __rich_measure__ returning Measurement; Measurement.get handles str and plain renderables.\nText rendering: Text.__rich_console__ -> wrap(console, width, justify, overflow, tab_size, no_wrap) -> divide_line per line -> Lines -> Text.render(console) builds Segments by combining span styles over offsets; console.get_style resolves style names through the ThemeStack then Style.parse.\nEnvironment detection (Console.__init__ and properties): is_terminal honors force_terminal, then TTY_COMPATIBLE (0/1), FORCE_COLOR (non empty means terminal), then file.isatty(); is_dumb_terminal checks TERM dumb/unknown; _detect_color_system uses COLORTERM truecolor/24bit, then the suffix of TERM (e.g. 256color) via _TERM_COLORS, Windows console features on win32; no_color from NO_COLOR non-empty; is_interactive from TTY_INTERACTIVE; width/height from COLUMNS/LINES, JUPYTER_COLUMNS/JUPYTER_LINES in Jupyter. Tests may pass _environ to Console.\n\n3. WHERE CHANGES GO\n- New option on a renderable: its __init__, __rich_console__ and __rich_measure__, and copy()/fit() style constructors if present (e.g. Panel.fit, Table.grid).\n- Width/wrapping issues: cells.py, _wrap.py, Text.wrap/divide, Segment.split_and_crop_lines, Table._calculate_column_widths.\n- Style/markup parsing: style.py (Style.parse), markup.py (render, escape), color.py (Color.parse).\n- Console behavior/env: console.py properties and __init__; export formats in _export_format.py and export_html/export_svg.\n- Tracebacks: traceback.py Traceback.extract and _render_stack; logging: logging.py RichHandler.\n- Add an entry to CHANGELOG.md under Unreleased (Added/Changed/Fixed) for user-visible changes.\n\n4. CONVENTIONS\n- Rich protocol: __rich_console__(self, console, options) -> RenderResult yielding Segments or other renderables; __rich_measure__(self, console, options) -> Measurement; __rich__ for casting.\n- Errors are specific subclasses from rich/errors.py; parsing errors raise StyleSyntaxError/MarkupError/ColorParseError.\n- Optional args default to None and are resolved at render time (e.g. justify None means inherit from options). Styles accept Union[str, Style] (StyleType) and are resolved via console.get_style.\n- Tests in tests/test_<module>.py. Typical pattern: console = Console(file=io.StringIO(), width=N, color_system=None or "truecolor", legacy_windows=False, force_terminal=...), console.print(x), assert console.file.getvalue() == expected. Alternatives: with console.capture() as capture then capture.get(); Console(record=True) then export_text(); console.render_lines; tests/render.py render(renderable) helper. tests/conftest.py removes FORCE_COLOR and NO_COLOR env vars. Expected outputs often contain raw ANSI escapes.\n\n5. PITFALLS\n- Always measure with cell_len / Segment.cell_length, never len(): wide CJK and emoji take two cells, zero-width and combining characters take zero. Crop with set_cell_size/chop_cells.\n- Text indices are character offsets (spans), while layout widths are cells.\n- Segment control segments (control is not None) have no width; keep them when splitting.\n- ConsoleOptions is immutable-ish; use options.update(...) or update_width to derive new options, never mutate.\n- Style addition is not commutative (right side wins); Style.null() and None both mean no style.\n- Rendering width < 1 yields nothing; height may be None.\n- Thread locals: buffer and theme stack are per thread; Live/Progress refresh on a background thread and redirect stdout/stderr through FileProxy.\n- Windows legacy console (legacy_windows) and Jupyter have separate code paths; tests set legacy_windows=False.\n- Older checkouts (2023) support Python 3.7+, use typing List/Optional/Tuple, and store width tables in rich/_cell_widths.py instead of rich/_unicode_data/; cells.py functions there take no unicode_version argument.\n'}


def find_ws():
    for cand in (os.environ.get("PWD"), os.environ.get("SWE_WS"), "/workspace"):
        if cand and os.path.isdir(os.path.join(cand, ".git")):
            return cand
    d = os.getcwd()
    while d != "/":
        if os.path.isdir(os.path.join(d, ".git")):
            return d
        d = os.path.dirname(d)
    sys.exit("error: repository not found")


ws = find_ws()
dest = os.path.join(ws, ".swetools")
os.makedirs(dest, exist_ok=True)
for name, src in FILES.items():
    with open(os.path.join(dest, name), "w") as fh:
        fh.write(src)
excl = os.path.join(ws, ".git", "info", "exclude")
os.makedirs(os.path.dirname(excl), exist_ok=True)
existing = open(excl).read() if os.path.exists(excl) else ""
if ".swetools/" not in existing:
    with open(excl, "a") as fh:
        fh.write("\n.swetools/\n")
for name, text in MAPS.items():
    pkg_dirs = {"fastapi": ["fastapi"], "rich": ["rich"], "requests": ["src/requests", "requests"], "httpx": ["httpx"]}[name]
    if any(os.path.isfile(os.path.join(ws, d, "__init__.py")) for d in pkg_dirs):
        with open(os.path.join(dest, "map.txt"), "w") as fh:
            fh.write(text)
        print("REPOSITORY MAP (also saved as .swetools/map.txt):")
        print(text)
        break
print("installed .swetools/ in the repository (git-excluded). Use with run_command:")
print("  python3 .swetools/locate.py TERM [TERM ...]      # find the code for the issue")
print("  python3 .swetools/show.py FILE START [END]         # numbered lines")
print("  python3 .swetools/edit.py FILE START END <<'EOF'   # replace lines START..END with the heredoc text")
print("  python3 .swetools/run.py /tmp/script.py              # run a Python script")
print("  python3 .swetools/check.py --repro /tmp/repro.py   # before/after repro + tests; VERDICT")
